      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Cefroxadine, a closely related oral cephem with a free amino side chain, is nearly 100% bioavailable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Loracarbef, with a phenylglycine amino side chain, is at least 80% bioavailable after oral dosing, supporting high absorption for amino-beta-lactams.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Cefazolin, which lacks the alpha-amino acid side chain, has only 1.5–2% oral bioavailability; this low value is less transferable because the query retains the amino side chain.",
